insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000030041', '30000000-0000-4000-8000-000000000037', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000300411', '40000000-0000-4000-8000-000000030041', 'O limite superior é a variável x.', 1), ('60000000-0000-4000-8000-000000300412', '40000000-0000-4000-8000-000000030041', 'O Teorema Fundamental recupera o integrando nesse limite.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000030041', '$F^{\prime}(x)=x^1.$', 'O Teorema Fundamental do Cálculo afirma que derivar uma integral acumulada cujo limite superior é x recupera o integrando avaliado em x. Portanto não é necessário calcular a integral antes de encontrar essa derivada.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000300411', '40000000-0000-4000-8000-000000030041', 'Reconheça a acumulação', '$F(x)$ acumula a função $t^1.$', 1), ('70000000-0000-4000-8000-000000300412', '40000000-0000-4000-8000-000000030041', 'Aplique o teorema', '$\frac{d}{dx}\int_0^x t^1 \,dt=x^1.$', 2), ('70000000-0000-4000-8000-000000300413', '40000000-0000-4000-8000-000000030041', 'Conclua', '$F^{\prime}(x)=x^1.$', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000030042', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000006', 'multiple_choice', 'easy', 'published', 'Se $F(x)=\int_0^x t^2 \,dt$, qual é $F^{\prime}(x)$?')
